<script setup>
import {t, locale} from "../i18n";
import {reactive,computed,ref,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {ArrowRight,ArrowLeft,ArrowUp,ArrowDown,Plus,Minus,Check,X,Copy,Lock,Unlock,Eye,EyeOff,Monitor,Smartphone,Tablet,Star,Heart,Zap,Layers,MousePointer2,ShoppingBag,Play,ChevronRight,ChevronDown,MessageSquare,Link,Search,MapPin,Image,FileText,Send,Download,RotateCcw} from 'lucide-vue-next';
import {simulationKinds,sceneLabels} from './simulationKinds';
const props=defineProps({feature:{type:Object,required:true},replay:{type:Number,default:0}});
const emit=defineEmits(['playing']);
if(!simulationKinds.includes(props.feature.kind))throw new Error('Unknown demo family: '+props.feature.kind);
const kind=props.feature.kind,type=props.feature.type;
const makeState=()=>({text:t('A little space for big ideas.'),size:30,bold:false,align:locale.value==='ar'?'right':'left',color:'#3565eb',gap:16,cols:2,device:'desktop',dark:false,rtl:false,open:false,tab:0,slide:0,amount:25,countdown:5,running:false,quantity:1,cart:0,sale:false,stock:true,submitted:false,step:1,email:'',name:'',error:'',field:'Email',role:'Visitor',logged:false,filter:'All',limit:3,query:'',binding:'Post title',post:0,layout:'Center',action:'Click',shared:t('Make something yours.'),override:'',copies:2,source:'WOFF2',family:'sans-serif',icon:'Star',resolved:false,locked:false,note:t('Can we try a shorter heading?'),notes:[],service:'Email',failed:false,phase:0,historyIndex:0,showMarkup:false,code:'<h3>A fresh idea</h3>\n<script>untrusted()<\/script>',sanitized:false,active:false,added:false,labels:['Overview','Details','Reviews'].map(value=>t(value)),items:[{id:1,label:'Heading',hidden:false,locked:false},{id:2,label:'Image',hidden:false,locked:false},{id:3,label:'Button',hidden:false,locked:false}],selection:1,popupViews:0,allowed:'Member',threshold:50,zoom:100,rotation:0,uploads:false});
const s=reactive(makeState()),walkStep=ref(-1),walking=ref(false),feedback=ref(''),preview=ref(null),root=ref(null),touched=ref(false),finished=ref(false),flash=ref(false);
function configure(){
 if(kind==='team')s.role='Full access';
 if(kind==='navigation')s.layout='Horizontal';
 if(kind==='payment')s.action='Buy now';
 if(kind==='countdown')s.action='Show message';
 const sources={'site-title':'Site title','site-logo':'Site title','post-excerpt':'Post excerpt','post-content':'Post excerpt','author-box':'Author','post-info':'Date','archive-title':'Site title','product-title':'Custom field','product-meta':'Stock','product-short-description':'Post excerpt'};
 if(sources[type])s.binding=sources[type];
 s.sizes={desktop:32};
 if(type==='email-marketing')s.service='Mailchimp';
 if(type==='webhooks')s.service='Webhook';
 if(type==='notifications')s.service='Slack';
 s.expanded=[];
}
configure();
let generation=0,timer;const waits=new Map();
const wait=ms=>new Promise(resolve=>{const id=setTimeout(()=>{waits.delete(id);resolve();},ms);waits.set(id,resolve);});
function stop(){generation++;walking.value=false;emit('playing',false);for(const[id,resolve]of waits){clearTimeout(id);resolve();}waits.clear();}
function reset(){stop();clearInterval(timer);Object.assign(s,makeState());configure();walkStep.value=-1;feedback.value='';touched.value=false;finished.value=false;markStart();}
// Visitors learn the canvas by cause and effect: the first control is marked until they use it, and the preview pulses whenever the example changes.
function markStart(){nextTick(()=>{const pane=root.value?.querySelector('.sim-control');pane?.querySelector('.sim-start')?.classList.remove('sim-start');pane?.querySelector('input:not([type=hidden]),select,textarea,button,[draggable=true]')?.classList.add('sim-start');});}
function interact(){if(walking.value)stop();touched.value=true;}
let flashTimer;
watch(s,()=>{flash.value=false;requestAnimationFrame(()=>{flash.value=true;clearTimeout(flashTimer);flashTimer=setTimeout(()=>flash.value=false,650);});},{deep:true});
onMounted(markStart);
defineExpose({reset});
onBeforeUnmount(()=>{stop();clearInterval(timer);clearTimeout(flashTimer);});
const labels=sceneLabels[kind];
const samplePosts=[{title:'A space for good ideas',author:'Alex Morgan',excerpt:'A few thoughts on designing with intention.',category:'Studio',date:'20 October 2026',price:'$24',stock:'12 in stock'},{title:'Every detail has a purpose',author:'Sam Lee',excerpt:'Exploring the details that make a place feel yours.',category:'Work',date:'21 October 2026',price:'$36',stock:'8 in stock'}];
const post=computed(()=>samplePosts[s.post]);
const articles=[{title:'Objects & space',category:'Studio'},{title:'A fresh perspective',category:'Work'},{title:'Made for everyday',category:'Studio'},{title:'Quiet details',category:'Work'},{title:'Form & feeling',category:'Studio'},{title:'A different angle',category:'Work'}];
const results=computed(()=>articles.filter(x=>(s.filter==='All'||x.category===s.filter)&&(!s.query||(t(x.title)+' '+x.title).toLocaleLowerCase(locale.value).includes(s.query.toLocaleLowerCase(locale.value)))).slice(0,s.limit));
const colors=['#3565eb','#1a1d23','#6d81b6'];
const responsiveSize=computed(()=>s.sizes[s.device]??s.sizes.desktop);
const fields=['Text','Textarea','Email','Phone','Number','Date','Time','Select','Radio','Checkbox','Acceptance','Upload','Password','Hidden','HTML'];
const safeCode=computed(()=>s.code.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,'').replace(/\son\w+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]*)/gi,''));
const fontSample=computed(()=>type.includes('icon')||type==='icon');
const isMulti=computed(()=>['multi-step','form','form-fields'].includes(type));
const quote=computed(()=>['testimonial','blockquote','reviews','testimonial-carousel'].includes(type));
const history=['A little space for big ideas.','Ideas look better live.','Make something yours.'];
const allowed=computed(()=>type==='maintenance'?(s.role==='Editor'):s.role===s.allowed||s.role==='Administrator');
const boundValue=computed(()=>{const p=post.value;const source={'Post title':p.title,'Post excerpt':p.excerpt,'Author':p.author,'Site title':'Objects & space.','Custom field':'Designed with intention.','Price':p.price,'Stock':p.stock,'Date':p.date};return source[s.binding]||p.title;});
const fontIcons={Star,Heart,Zap,Layers};
const nodeSize=computed(()=>type==='spacer'?s.gap:s.size);
function duplicate(){if(s.locked)return;s.items.push({id:Date.now(),label:'Heading copy',hidden:false,locked:false});feedback.value='Element duplicated in this example.';}
function move(index,delta){const to=index+delta;if(to<0||to>=s.items.length||s.items[index].locked)return;[s.items[index],s.items[to]]=[s.items[to],s.items[index]];}
function dragStart(event,index){event.dataTransfer.setData('text/plain',String(index));event.dataTransfer.effectAllowed='move';}
function drop(event,index){const from=Number(event.dataTransfer.getData('text/plain'));if(!Number.isInteger(from)||from<0||from>=s.items.length||s.items[from].locked)return;const[item]=s.items.splice(from,1);s.items.splice(index,0,item);}
function submitForm(){s.error='';if(!s.email.trim()||!/^\S+@\S+\.\S+$/.test(s.email)){s.error='Add a valid example email to continue.';return;}if(isMulti.value&&s.step===1){s.step=2;return;}s.submitted=true;feedback.value='Example complete. Nothing was sent or saved to a server.';}
function downloadExample(format='json'){const content=format==='csv'?'Name,Status\nDemo contact,Read\nSample enquiry,Unread\n':JSON.stringify({example:true,format:'Zadex demonstration only',page:{title:s.shared},elements:['Heading','Button']},null,2);const blob=new Blob([content],{type:format==='csv'?'text/csv':'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='zadex-sample.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);feedback.value='Downloaded a sample file, not a real site export.';}
function inspectImport(event){const file=event.target.files?.[0];if(!file)return;if(file.size>100000){feedback.value='Choose an example JSON file under 100 KB.';return;}file.text().then(text=>{try{const parsed=JSON.parse(text);if(!parsed.example)throw new Error();s.shared=String(parsed.page?.title||'Imported example').slice(0,100);s.added=true;feedback.value='Sample JSON imported locally.';}catch{feedback.value='This is not a valid demonstration export.';}});}
function sanitize(){s.sanitized=true;feedback.value='Script removed in this illustration. No code is executed.';}
function startCountdown(){clearInterval(timer);s.countdown=5;s.running=true;timer=setInterval(()=>{s.countdown--;if(s.countdown<=0){clearInterval(timer);s.running=false;s.open=true;}},1000);}
function runWorkflow(){s.phase=3;s.submitted=true;feedback.value=s.failed?'Example delivery failed; a retry is queued. No request was sent.':'Example action completed locally. No integration was contacted.';}
function jump(){s.open=true;feedback.value=type==='read-more'?'The example excerpt expanded.':'Jumped to the example anchor.';}
function toggleAccordion(index){if(s.expanded.includes(index)){s.expanded=s.expanded.filter(value=>value!==index);}else{s.expanded=s.active?[...s.expanded,index]:[index];}}
function applyStep(index){walkStep.value=index;feedback.value='';switch(kind){
case 'edit':if(index===1)s.text=t('Your ideas. Made real.');if(index===2){s.bold=true;s.align='center';}break;
case 'layout':s.cols=[1,2,3][index];s.gap=[8,16,28][index];break;
case 'organize':if(index===1)move(2,-1);if(index===2)duplicate();break;
case 'history':s.historyIndex=[0,2,0][index];break;
case 'responsive':s.device=index===0?'desktop':'mobile';if(index===2)s.sizes.mobile=24;break;
case 'appearance':s.dark=index>0;s.rtl=index===2;break;
case 'style':s.color=colors[index];s.gap=12+index*8;s.size=24+index*5;break;
case 'motion':s.amount=[0,50,90][index];s.active=index>0;break;
case 'conditions':s.role=['Visitor','Editor','Member'][index];if(type==='maintenance'&&index===2)s.role='Editor';break;
case 'theme':s.tab=[0,1,3][index];s.active=index>0;break;
case 'dynamic':s.binding=index===0?'Post title':type.includes('product')?'Price':'Custom field';s.post=index===2?1:0;break;
case 'collection':s.filter=index===1?'Studio':'All';s.limit=index===2?6:3;break;
case 'popup':s.layout=index===1?'Side panel':'Center';s.open=index===2;break;
case 'form':if(index===0)s.field='Email';if(index===1){s.email='hello@example.test';s.step=isMulti.value?2:1;}if(index===2){s.email='hello@example.test';s.step=2;submitForm();}break;
case 'workflow':s.phase=index+1;if(index===2)runWorkflow();break;
case 'reuse':s.copies=index===0?1:3;if(index===2)s.shared=t('A better idea. Everywhere.');break;
case 'transfer':s.phase=index;s.added=index===2;break;
case 'assets':s.icon=['Star','Heart','Zap'][index];s.family=['sans-serif','serif','monospace'][index];s.uploads=index===2;break;
case 'team':if(index===1){s.notes.push(s.note);s.resolved=true;}if(index===2){s.role='Content only';s.locked=true;}break;
case 'performance':s.showMarkup=index>0;s.active=index===2;break;
case 'admin':s.tab=index;s.resolved=index>0;s.added=index===2;break;
case 'tabs':s.tab=index;if(index===2)s.labels[2]=t('Your details');break;
case 'accordion':s.tab=index;s.expanded=index===0?[]:s.active?[...new Set([...s.expanded,index-1])]:[index-1];break;
case 'media':s.slide=index;s.zoom=100+index*10;s.open=index===2;break;
case 'carousel':s.slide=index;break;
case 'links':s.icon=['Star','Heart','Zap'][index];s.active=index===2;if(index===2)feedback.value='Local action preview. No external destination opened.';break;
case 'notice':s.tab=index;s.open=index===2;break;
case 'metric':s.amount=[0,55,90][index];break;
case 'countdown':s.countdown=[5,3,0][index];s.open=index===2;break;
case 'flip':s.open=index===1;break;
case 'code':s.showMarkup=index>0;s.sanitized=index===2;break;
case 'search':s.query=['',t(articles[0].title).slice(0,4),t(articles[4].title).slice(0,4)][index];break;
case 'navigation':s.open=index>0;s.tab=index;break;
case 'commerce':s.quantity=index+1;s.cart=index===2?3:0;s.sale=index===1;s.stock=index!==1;s.tab=index;break;
case 'payment':s.tab=index;s.open=index===2;break;
case 'embed':s.open=index>0;s.active=index===2;break;
case 'hotspot':s.tab=index;s.open=index>0;break;
case 'anchor':s.open=index>0;s.tab=index;break;
}}
async function walkthrough(){stop();clearInterval(timer);Object.assign(s,makeState());configure();const token=generation;walking.value=true;emit('playing',true);const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;for(let i=0;i<3;i++){if(token!==generation)return;applyStep(i);if(!reduced)await wait(1350);}if(token===generation){walking.value=false;finished.value=true;emit('playing',false);}}
watch(()=>props.replay,value=>{if(value>0)walkthrough();},{immediate:true});
</script>
<template>
<div ref="root" class="sim" :class="{'sim-fresh':!touched&&!walking}" :data-kind="kind" :style="{'--sim-controls-label':JSON.stringify(t('Change a setting')),'--sim-preview-label':JSON.stringify(t('Live preview'))}" @pointerdown="interact" @keydown.capture="interact" @input.capture="interact" @change.capture="interact">
 <div class="sim-workspace" :class="{'sim-dark':s.dark,'sim-rtl':s.rtl,'sim-flash':flash}" :dir="s.rtl||locale==='ar'?'rtl':'ltr'">
  <template v-if="kind==='edit'">
   <div class="sim-control"><label>{{t("Text")}}<input v-model="s.text" maxlength="90" :aria-label='t("Demo heading text")'></label><div class="sim-inline"><label>{{t("Size")}}<input v-model.number="s.size" type="range" min="18" max="42" :aria-label='t("Demo text size")'></label><button :aria-pressed="s.bold" @click="s.bold=!s.bold">{{t("Bold")}}</button></div><div class="sim-segments" :aria-label='t("Text alignment")'><button v-for="a in ['left','center','right']" :key="a" :aria-pressed="s.align===a" @click="s.align=a">{{t(a)}}</button></div></div>
   <div class="sim-sheet"><div class="sim-sample-nav">{{t("Objects & space.")}}<span>{{t("Studio / Work")}}</span></div><h4 class="sim-selected" :style="{fontSize:s.size+'px',fontWeight:s.bold?700:400,textAlign:s.align,transform:type==='text-path'?'rotate(-5deg)':null}">{{s.text||t('Your heading')}}</h4><p>{{t("Click a setting. Make a little change.")}}<br>{{t("See it happen, right here.")}}</p><span class="sim-faux-button">{{t("A little more possibility")}}<ArrowRight :size="13"/></span></div>
  </template>
  <template v-else-if="kind==='layout'">
   <div class="sim-control"><label>{{t("Columns")}}<select v-model.number="s.cols" :aria-label='t("Demo columns")'><option :value="1">{{t("One column")}}</option><option :value="2">{{t("Two columns")}}</option><option :value="3">{{t("Three columns")}}</option><option :value="4">{{t("Four columns")}}</option></select></label><label>{{t(type==='divider'?'Line weight':type==='spacer'?'Spacer height':'Gap')}} · {{t(s.gap)}} {{t("px")}}<input v-model.number="s.gap" type="range" min="4" max="40" :aria-label='t("Demo layout spacing")'></label></div>
   <div class="sim-sheet"><div class="sim-sample-nav">{{t("A place for your ideas.")}}</div><template v-if="type==='divider'||type==='spacer'"><p>{{t("A little breathing room.")}}</p><div :style="{height:s.gap+'px',background:type==='divider'?'#3565eb':'#eef2ff',margin:'15px 0'}"></div><p>{{t("Every detail, considered.")}}</p></template><div v-else class="sim-layout-grid" :style="{gridTemplateColumns:`repeat(${s.cols},minmax(0,1fr))`,gap:s.gap+'px'}"><div v-for="n in 4" :key="n"><Layers :size="20"/><strong>{{t(['An idea','A little shape','A detail','The next thing'][n-1])}}</strong></div></div><p class="sim-caption">{{t("The same four elements. A different structure.")}}</p></div>
  </template>
  <template v-else-if="kind==='organize'">
   <div class="sim-control"><strong>{{t("Page structure")}}</strong><p>{{t("Drag a row, or use the arrow buttons.")}}</p><div v-for="(item,index) in s.items" :key="item.id" class="sim-tree-row" draggable="true" @dragstart="dragStart($event,index)" @dragover.prevent @drop.prevent="drop($event,index)"><span>{{t(item.label)}}</span><button @click="move(index,-1)" :disabled="index===0||item.locked" :aria-label="t('Move {element} up',{element:t(item.label)})"><ArrowUp :size="13"/></button><button @click="move(index,1)" :disabled="index===s.items.length-1||item.locked" :aria-label="t('Move {element} down',{element:t(item.label)})"><ArrowDown :size="13"/></button><button @click="item.hidden=!item.hidden" :aria-label="t(item.hidden?'Show {element}':'Hide {element}',{element:t(item.label)})"><EyeOff v-if="item.hidden" :size="13"/><Eye v-else :size="13"/></button><button @click="item.locked=!item.locked" :aria-label="t(item.locked?'Unlock {element}':'Lock {element}',{element:t(item.label)})"><Lock v-if="item.locked" :size="13"/><Unlock v-else :size="13"/></button></div><button @click="duplicate" class="sim-action"><Copy :size="13"/>{{t("Duplicate heading")}}</button></div><div class="sim-sheet"><div v-for="item in s.items.filter(x=>!x.hidden)" :key="item.id" class="sim-tree-preview"><Lock v-if="item.locked" :size="13"/><strong v-if="item.label.includes('Heading')">{{t("A fresh perspective.")}}</strong><div v-else-if="item.label==='Image'" class="sim-art art-0" role="img" :aria-label='t("Sample geometric artwork")'></div><span v-else class="sim-faux-button">{{t("Explore the idea")}}</span></div></div>
  </template>
  <template v-else-if="kind==='history'">
   <div class="sim-control"><strong>{{t(type==='revisions'?'Saved revisions':'History')}}</strong><button v-for="(text,index) in history" :key="text" class="sim-history-row" :aria-pressed="s.historyIndex===index" @click="s.historyIndex=index"><Check v-if="s.historyIndex===index" :size="13"/>{{t(['Original heading','First idea','Latest edit'][index])}}</button><div class="sim-inline"><button :disabled="s.historyIndex===0" @click="s.historyIndex--"><ArrowLeft :size="13"/>{{t("Undo")}}</button><button :disabled="s.historyIndex===2" @click="s.historyIndex++">{{t("Redo")}}<ArrowRight :size="13"/></button></div></div><div class="sim-sheet"><span class="sim-caption">{{t("Restorable example versions")}}</span><h4>{{t(history[s.historyIndex])}}</h4><p>{{t("Explore a different direction. The earlier idea is still here.")}}</p></div>
  </template>
  <template v-else-if="kind==='responsive'">
   <div class="sim-control"><label>{{t("Preview screen")}}<select v-model="s.device" :aria-label='t("Demo device")'><option value="widescreen">{{t("Widescreen")}}</option><option value="desktop">{{t("Desktop")}}</option><option value="laptop">{{t("Laptop")}}</option><option value="tablet-xl">{{t("Large tablet")}}</option><option value="tablet">{{t("Tablet")}}</option><option value="mobile-xl">{{t("Large mobile")}}</option><option value="mobile">{{t("Mobile")}}</option></select></label><label>{{t("Heading size ·")}} {{t(responsiveSize)}} {{t("px")}}<input :value="responsiveSize" @input="s.sizes[s.device]=Number($event.target.value)" type="range" min="18" max="36" :aria-label='t("Responsive heading size")'></label><label class="sim-check"><input type="checkbox" v-model="s.active">{{t("Hide sample image on mobile")}}</label><small>{{t(s.device==='desktop'?'Base desktop value':s.sizes[s.device]?'Override for this screen. Desktop is unchanged.':'Inherited from desktop. Change to override this screen.')}}</small></div><div class="sim-device-area"><div class="sim-sheet sim-device-sheet" :class="'device-'+s.device"><div class="sim-sample-nav"><Monitor v-if="!s.device.startsWith('mobile')" :size="14"/><Smartphone v-else :size="14"/>{{t("Objects & space.")}}</div><h4 :style="{fontSize:responsiveSize+'px'}">{{t("Room for your ideas.")}}</h4><div v-if="!(s.device.startsWith('mobile')&&s.active)" class="sim-art art-1" role="img" :aria-label='t("Sample geometric artwork")'></div><p>{{t("Your design. Every screen.")}}</p><small>{{t("Preview scaled to this canvas.")}}</small></div></div>
  </template>
  <template v-else-if="kind==='appearance'">
   <div class="sim-control"><label class="sim-check"><input type="checkbox" v-model="s.dark">{{t("Dark editor chrome")}}</label><label class="sim-check"><input type="checkbox" v-model="s.rtl">{{t("Arabic / RTL")}}</label><small>{{t("The page stays a white sheet. The surrounding controls follow the appearance.")}}</small></div><div class="sim-sheet"><div class="sim-sample-nav">{{t("Zadex")}}<span class="brand-dot"></span></div><h4>{{t(s.rtl?'أفكارك. على أرض الواقع.':'Your ideas. Made real.')}}</h4><p>{{t(s.rtl?'عدّل النصوص وشاهد التصميم مباشرة.':'Edit your text. See your design come to life.')}}</p><span class="sim-faux-button">{{t(s.rtl?'ابدأ التصميم':'Start creating')}}<ArrowRight :size="13"/></span></div>
  </template>
  <template v-else-if="kind==='style'">
   <div class="sim-control"><div class="sim-swatches" :aria-label='t("Demo style color")'><button v-for="color in colors" :key="color" :style="{background:color}" :aria-label="t('Use {color}',{color})" :aria-pressed="s.color===color" @click="s.color=color"></button></div><label>{{t("Typography ·")}} {{t(s.size)}} {{t("px")}}<input v-model.number="s.size" type="range" min="18" max="36" :aria-label='t("Style font size")'></label><label>{{t(type==='position'?'Horizontal offset':'Shared spacing')}} · {{t(s.gap)}} {{t("px")}}<input v-model.number="s.gap" type="range" min="4" max="32" :aria-label='t("Shared spacing")'></label></div><div class="sim-sheet"><div class="sim-style-examples" :style="{gap:s.gap+'px'}"><div v-for="n in (type==='position'?1:2)" :key="n" :style="{padding:s.gap+'px',transform:type==='position'?`translateX(${s.gap-16}px)`:null}"><h4 :style="{color:s.color,fontSize:s.size+'px'}">{{t(n===1?'Your first idea.':'The next one.')}}</h4><span class="sim-faux-button" :style="{background:s.color}">{{t("Connected by design")}}</span></div></div></div>
  </template>
  <template v-else-if="kind==='motion'">
   <div class="sim-control"><label>{{t(type==='sticky'?'Scroll position':'Timeline progress')}} · {{t(s.amount)}}%<input v-model.number="s.amount" type="range" min="0" max="100" :aria-label='t("Animation progress")'></label><button class="sim-action" @click="s.active=!s.active;s.amount=s.active?90:0"><Play :size="13"/>{{t(s.active?'Replay effect':'Trigger effect')}}</button><small>{{t("A local illustration of the selected motion setting.")}}</small></div><div class="sim-sheet sim-motion-scene"><div class="sim-motion-header" :class="{stuck:type==='sticky'&&s.amount>35}">{{t("Objects & space.")}}</div><div class="sim-motion-object" :style="{transform:type==='sticky'?`translateY(${-s.amount/3}px)`:`translateY(${20-s.amount/5}px) rotate(${s.amount/8}deg) scale(${.8+s.amount/500})`,opacity:.35+s.amount/155}"><Layers :size="40"/><strong>{{t(type==='lottie'?'Animation preview':'A little movement.')}}</strong></div><p>{{t(type==='sticky'&&s.amount>35?'Sticky header remains visible.':'Move the timeline to explore the effect.')}}</p></div>
  </template>
  <template v-else-if="kind==='conditions'">
