  <template v-else-if="kind==='links'">
   <div class="sim-control"><label>{{t("Label")}}<input v-model="s.shared" maxlength="45" :aria-label='t("Demo action label")'></label><label>{{t("Icon")}}<select v-model="s.icon" :aria-label='t("Demo action icon")'><option :value='"Star"'>{{t("Star")}}</option><option :value='"Heart"'>{{t("Heart")}}</option><option :value='"Zap"'>{{t("Zap")}}</option><option :value='"Layers"'>{{t("Layers")}}</option></select></label><label class="sim-check"><input type="checkbox" v-model="s.bold">{{t("Rounded presentation")}}</label></div><div class="sim-sheet sim-links-scene"><h4>{{t("A clear next step.")}}</h4><div class="sim-action-stack"><button v-for="n in (['social-icons','share-buttons','bio-links','icon-list','floating-buttons'].includes(type)?3:1)" :key="n" class="sim-action" :style="{borderRadius:s.bold?'30px':'6px'}" @click="feedback=t('Local action previewed. No external action was taken.')"><component :is="fontIcons[s.icon]" :size="18"/>{{n===1?s.shared:t(['Studio','Portfolio','Get in touch'][n-1])}}<ArrowRight :size="13"/></button></div><p class="sim-caption">{{t("Links are local demonstrations.")}}</p></div>
  </template>
  <template v-else-if="kind==='notice'">
   <div class="sim-control"><label>{{t("Headline")}}<input v-model="s.shared" maxlength="55" :aria-label='t("Demo content headline")'></label><label>{{t("Presentation")}}<select v-model.number="s.tab" :aria-label='t("Demo presentation")'><option :value="0">{{t("Simple")}}</option><option :value="1">{{t("Featured")}}</option><option :value="2">{{t("Compact")}}</option></select></label><button @click="s.open=!s.open">{{t(type==='alert'?(s.open?'Show notice':'Dismiss notice'):'Preview action')}}</button></div><div class="sim-sheet"><template v-if="type==='alert'&&s.open"><Check :size="24"/><p>{{t("Notice dismissed. Show it again to replay.")}}</p></template><template v-else><span v-if="type.includes('price')" class="sim-caption">{{t("Illustrative offer · not Zadex pricing")}}</span><span v-else-if="quote" class="sim-caption">{{t("Illustrative quote · not a Zadex testimonial")}}</span><h4 :class="{'sim-selected':s.tab===1}">{{quote?'“'+s.shared+'”':s.shared}}</h4><strong v-if="type.includes('price')" class="sim-price">$24 <small>{{t("/ example item")}}</small></strong><p>{{t(quote?'Demo author · Sample content':'A considered message and a clear next step.')}}</p><span class="sim-faux-button">{{t(type==='alert'?'Information':type.includes('price')?'Explore the sample':'Discover more')}}</span></template></div>
  </template>
  <template v-else-if="kind==='metric'">
   <div class="sim-control"><label>{{t("Value ·")}} {{t(s.amount)}}<input v-model.number="s.amount" type="range" min="0" max="100" :aria-label='t("Demo metric value")'></label><button @click="s.amount=s.amount===100?0:100" class="sim-action">{{t(type==='counter'?'Run count':'Preview full value')}}</button></div><div class="sim-sheet sim-metric"><h4>{{t(type==='counter'?'An idea worth counting.':type.includes('rating')?'A considered rating.':'A little more progress.')}}</h4><strong v-if="type==='counter'" class="sim-big-number">{{t(s.amount)}}</strong><div v-else-if="type.includes('rating')" class="sim-stars" :aria-label="t('{count} out of 5 stars',{count:Math.round(s.amount/20)})"><Star v-for="n in 5" :key="n" :size="27" :fill="n<=Math.round(s.amount/20)?'#3565eb':'none'"/></div><template v-else><div class="sim-meter" role="progressbar" :aria-label='t("Example progress")' :aria-valuenow="s.amount" aria-valuemin="0" aria-valuemax="100"><span :style="{width:s.amount+'%'}"></span></div><span>{{t(s.amount)}}%</span></template><p class="sim-caption">{{t("Illustrative value, not product performance or reviews.")}}</p></div>
  </template>
  <template v-else-if="kind==='countdown'">
   <div class="sim-control"><button class="sim-action" @click="startCountdown" :disabled="s.running"><Play :size="13"/>{{t("Start 5-second example")}}</button><label>{{t("End action")}}<select v-model="s.action"><option :value='"Show message"'>{{t("Show message")}}</option><option :value='"Open popup"'>{{t("Open popup")}}</option><option :value='"Redirect preview"'>{{t("Redirect preview")}}</option></select></label></div><div class="sim-sheet sim-metric"><h4>{{t("A little anticipation.")}}</h4><strong class="sim-big-number">00 : {{t(String(s.countdown).padStart(2,'0'))}}</strong><p v-if="s.open&&s.countdown===0">{{t(s.action==='Open popup'?'The example popup would open.':s.action==='Redirect preview'?'Redirect illustrated. No navigation performed.':'Time for your next idea.')}}</p><p v-else>{{t("Seconds until the selected end action.")}}</p></div>
  </template>
  <template v-else-if="kind==='flip'">
   <div class="sim-control"><button class="sim-action" @click="s.open=!s.open">{{t(s.open?'Show front':'Flip the box')}}<RotateCcw :size="13"/></button><small>{{t("Two sides, one content element.")}}</small></div><div class="sim-sheet sim-flip-space"><div class="sim-flip" :class="{flipped:s.open}"><div class="sim-flip-front"><Layers :size="35"/><h4>{{t("A first impression.")}}</h4><p>{{t("There’s more on the other side.")}}</p></div><div class="sim-flip-back"><Heart :size="35"/><h4>{{t("A little more depth.")}}</h4><p>{{t("Your second message lives here.")}}</p></div></div></div>
  </template>
  <template v-else-if="kind==='code'">
   <div class="sim-control"><label>{{t("Illustrative markup")}}<textarea v-model="s.code" maxlength="500" :aria-label='t("Demo markup")'></textarea></label><button class="sim-action" @click="sanitize">{{t("Preview safe output")}}<Check :size="13"/></button><small>{{t("Plain-text demonstration only. No code in this example is executed.")}}</small></div><div class="sim-sheet"><h4>{{t(type==='code-highlight'?'A little clarity for code.':'A safer place for markup.')}}</h4><pre><code>{{s.sanitized?safeCode:s.code}}</code></pre><p class="sim-caption">{{t(type==='attributes'?'Allowed IDs and classes; no script-capable attributes.':'The plugin does not offer custom CSS or JavaScript entry.')}}</p></div>
  </template>
  <template v-else-if="kind==='search'">
   <div class="sim-control"><label>{{t("Search example content")}}<input v-model="s.query" :placeholder='t("Try space or form…")' type="search" :aria-label='t("Demo instant search")'></label><small>{{t("Results update as you type. These are local sample posts.")}}</small></div><div class="sim-sheet"><h4>{{t("Find your next idea.")}}</h4><div v-for="item in results" :key="item.title" class="sim-search-result"><Search :size="14"/><span>{{t(item.title)}}<small>{{t(item.category)}}</small></span><ArrowRight :size="13"/></div><p v-if="!results.length">{{t("No example posts match. Try “space”.")}}</p></div>
  </template>
  <template v-else-if="kind==='navigation'">
   <div class="sim-control"><label>{{t("Navigation layout")}}<select v-model="s.layout"><option :value='"Horizontal"'>{{t("Horizontal")}}</option><option :value='"Vertical"'>{{t("Vertical")}}</option><option :value='"Mobile menu"'>{{t("Mobile menu")}}</option></select></label><button @click="s.open=!s.open" class="sim-action">{{t(s.open?'Close dropdown':'Open dropdown')}}<ChevronDown :size="13"/></button></div><div class="sim-sheet"><div class="sim-example-menu" :class="{vertical:s.layout!=='Horizontal'}"><strong>{{t("Objects & space.")}}</strong><button v-for="(name,index) in ['Studio','Work','Contact']" :key="name" :aria-pressed="s.tab===index" @click="s.tab=index;s.open=index===1">{{t(name)}}</button></div><div v-if="s.open" class="sim-mega-content"><div><strong>{{t("Explore the studio")}}</strong><p>{{t("Furniture")}}<br>{{t("Objects")}}<br>{{t("Spaces")}}</p></div><div class="sim-art art-0"></div></div><span class="sim-caption">{{t("Home /")}} {{t(['Studio','Work','Contact'][s.tab])}}</span><h4>{{t(['A place for ideas.','Thoughtfully made work.','Say a little hello.'][s.tab])}}</h4></div>
  </template>
  <template v-else-if="kind==='commerce'">
   <div class="sim-control"><template v-if="type==='my-account'"><label>{{t("Account section")}}<select v-model.number="s.tab" :aria-label='t("Example account section")'><option :value="0">{{t("Dashboard")}}</option><option :value="1">{{t("Orders")}}</option><option :value="2">{{t("Addresses")}}</option></select></label><small>{{t("A fictional customer account. No login or customer records are loaded.")}}</small></template><template v-else><label>{{t("Quantity")}}<input v-model.number="s.quantity" type="number" min="1" max="10" :aria-label='t("Sample product quantity")' @change="s.quantity=Math.min(10,Math.max(1,Number(s.quantity)||1))"></label><label class="sim-check"><input type="checkbox" v-model="s.sale">{{t("Show sale price")}}</label><label class="sim-check"><input type="checkbox" v-model="s.stock">{{t("In stock")}}</label><button :disabled="!s.stock" @click="s.cart+=Math.min(10,Math.max(1,Number(s.quantity)||1))" class="sim-action"><ShoppingBag :size="14"/>{{t("Add to demo cart")}}</button></template></div><div class="sim-sheet"><span class="sim-caption">{{t("Sample store · Requires WooCommerce in the plugin")}}</span><template v-if="type==='my-account'"><h4>{{t(['Your account.','Your orders.','Your addresses.'][s.tab])}}</h4><p>{{t(['Welcome to a sample account dashboard.','Example order #DEMO-01 · Studio print · $24','A fictional studio address is shown here.'][s.tab])}}</p><div class="sim-file-row"><Check :size="14"/>{{t("Local account illustration")}}</div></template><template v-else-if="type==='checkout'"><h4>{{t(s.submitted?'Order flow previewed.':'A considered checkout.')}}</h4><template v-if="!s.submitted"><label>{{t("Example contact")}}<input v-model="s.email" :placeholder='t("hello@example.test")' :aria-label='t("Example checkout contact")'></label><div class="sim-cart-summary">{{t("Studio print ×")}} {{t(s.quantity)}}<strong>${{t(s.quantity*(s.sale?18:24))}}</strong></div><button class="sim-action" @click="s.submitted=true">{{t("Preview order confirmation")}}</button></template><p v-else>{{t("No order placed. No payment processed.")}}</p></template><template v-else-if="type==='purchase-summary'"><h4>{{t("Thanks for the idea.")}}</h4><div class="sim-file-row">{{t("Sample order #DEMO-01")}}</div><div class="sim-cart-summary">{{t("Studio print ×")}} {{t(s.quantity)}}<strong>${{t(s.quantity*(s.sale?18:24))}}</strong></div><p>{{t("Illustrative order summary, not a real purchase.")}}</p></template><template v-else><div class="sim-art sim-product-art art-1"></div><h4>{{t("Studio print.")}}</h4><span class="sim-price"><del v-if="s.sale">$24</del> ${{t(s.sale?18:24)}}</span><p>{{t(s.stock?'In stock':'Out of stock')}} {{t("· SKU: DEMO-01")}}</p><div class="sim-cart-summary"><ShoppingBag :size="16"/>{{t('Items: {count}',{count:s.cart})}}<strong>${{t(s.cart*(s.sale?18:24))}}</strong></div></template><small>{{t("No purchase, checkout or payment is performed.")}}</small></div>
  </template>
  <template v-else-if="kind==='payment'">
   <div class="sim-control"><label>{{t("Action")}}<select v-model="s.action"><option :value='"Buy now"'>{{t("Buy now")}}</option><option :value='"Donate"'>{{t("Donate")}}</option><option :value='"Subscribe"'>{{t("Subscribe")}}</option></select></label><label>{{t("Sample amount")}}<input v-model.number="s.quantity" type="number" min="1" max="100" :aria-label='t("Example payment amount")'></label><small>{{t('Real payments require configuring {provider} in WordPress.',{provider:type==='paypal-button'?'PayPal':'Stripe'})}}</small></div><div class="sim-sheet sim-payments"><Lock :size="25"/><h4>{{t("A clear next step.")}}</h4><p>{{t(type==='paypal-button'?'PayPal':'Stripe')}} {{t("button preview · $")}} {{t(s.quantity)}}</p><button class="sim-action" @click="s.open=true">{{t(s.action)}}<ArrowRight :size="13"/></button><p v-if="s.open" class="sim-caption">{{t("Destination preview only. No payment provider was opened and no money was charged.")}}</p></div>
  </template>
  <template v-else-if="kind==='embed'">
   <div class="sim-control"><label>{{t("Example title")}}<input v-model="s.shared" maxlength="45" :aria-label='t("Demo embed title")'></label><button class="sim-action" @click="s.open=!s.open">{{t(s.open?'Hide embed preview':'Open embed preview')}}</button><small>{{t('No connection is made to {provider}.',{provider:type==='google-maps'?'Google Maps':type==='soundcloud'?'SoundCloud':type==='facebook'?'Facebook':t('external video provider')})}}</small><label v-if="type==='video-playlist'">{{t("Playlist chapter")}}<select v-model.number="s.tab" @change="preview&&(preview.currentTime=s.tab*7)"><option :value="0">{{t("Insert a section")}}</option><option :value="1">{{t("Edit your heading")}}</option><option :value="2">{{t("Preview your layout")}}</option></select></label></div><div class="sim-sheet"><template v-if="s.open&&['video','video-playlist'].includes(type)"><h4>{{s.shared}}</h4><video ref="preview" controls muted playsinline preload="metadata" class="sim-local-video" poster="/media/zadex-editor-poster.jpg" src="/media/zadex-in-action.mp4" :aria-label='t("Local sample video for the video element simulation")'></video><p class="sim-caption">{{t("Local sample recording. No streaming service is connected.")}}</p></template><div v-else class="sim-embed"><MapPin v-if="type==='google-maps'" :size="33"/><Play v-else :size="33"/><strong>{{s.shared}}</strong><p>{{t(s.open?(type==='google-maps'?'Map placement preview • no map tiles loaded':type==='soundcloud'?'Audio player placement • no audio loaded':type==='facebook'?'Social embed placement • SDK not loaded':'Local player preview is closed'):'An optional service, placed inside your design.')}}</p><button v-if="s.open" @click="s.active=!s.active">{{t(s.active?'Preview paused':'Preview selected')}}</button></div></div>
  </template>
  <template v-else-if="kind==='hotspot'">
   <div class="sim-control"><label>{{t("Point label")}}<input v-model="s.shared" maxlength="45" :aria-label='t("Hotspot point label")'></label><small>{{t("Choose a point on the sample artwork.")}}</small></div><div class="sim-sheet"><div class="sim-hotspot-art sim-art art-0"><button v-for="(point,index) in [{x:30,y:35},{x:65,y:60},{x:40,y:75}]" :key="index" :style="{left:point.x+'%',top:point.y+'%'}" :aria-label="t('Open hotspot {number}',{number:index+1})" :aria-pressed="s.open&&s.tab===index" @click="s.open=s.tab!==index||!s.open;s.tab=index"><Plus :size="14"/></button><div v-if="s.open" class="sim-hotspot-label">{{s.shared}}<small>{{t("Point")}} {{t(s.tab+1)}}</small></div></div></div>
  </template>
  <template v-else-if="kind==='anchor'">
   <div class="sim-control"><label>{{t("Anchor ID")}}<input v-model="s.shared" maxlength="30" :aria-label='t("Example anchor ID")'></label><button @click="jump" class="sim-action">{{t(type==='read-more'?'Read more':'Jump to target')}}<ArrowDown :size="13"/></button></div><div class="sim-sheet"><h4>{{t("A little introduction.")}}</h4><p>{{t("A few words to begin the story.")}}</p><div v-if="s.open" class="sim-anchor-target"><span class="sim-caption">#{{s.shared.replaceAll(' ','-').toLowerCase()}}</span><h4>{{t("And a little more.")}}</h4><p>{{t("The rest of the example content is here, ready to explore.")}}</p></div><span v-else class="sim-caption">{{t("The next part waits below.")}}</span></div>
  </template>
 </div>
 <div class="sim-walkthrough" :aria-label='t("Simulation walkthrough")'><button v-for="(label,index) in labels" :key="label" :class="{done:walkStep>index}" :aria-pressed="walkStep===index" @click="stop();applyStep(index)"><span><Check v-if="walkStep>index" :size="11"/><template v-else>{{t(index+1)}}</template></span>{{t(label)}}</button></div>
 <p class="sim-status" role="status">{{t(finished&&!touched&&!walking?'Your turn. Change any setting and watch the preview update.':feedback||(walkStep>=0?labels[walkStep]:'Start with the highlighted setting, or watch how it works.'))}}</p>
</div>
</template>




